export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"ja","term":"コインとトークンの違い","aka":[],"short":"コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。","body":[["コインの代表例は、",["ビットコイン","bitcoin"],"のBTC、",["イーサリアム","ethereum"],"のETH、ソラナのSOLです。これらはそれぞれのチェーンのネイティブ資産で、",["送金手数料","withdrawal-fee"],"（",["ガス代","gas-fee"],"）の支払いやネットワークの安全確保に使われます。"],["トークンは、イーサリアムのERC-20規格のように、既存チェーンの上で",["スマートコントラクト","smart-contract"],"として発行されます。USDTやUSDCなどの",["ステーブルコイン","stablecoin"],"、UNIのようなガバナンストークンが代表例です。同じUSDTでも、イーサリアム版、トロン版、ソラナ版など複数のチェーンで発行されています。"],"実務で最も重要なのは手数料です。トークンを送るときも、そのチェーンのコインでガス代を払う必要があります。また、取引所で入出金するときは、どのチェーン上のトークンかを必ず一致させなければなりません。なお日常会話では両者をまとめて「コイン」と呼ぶことも多く、厳密には使い分けられていません。"],"example":"例えば、ウォレットに500 USDC（イーサリアム上のERC-20トークン）があっても、ETHが0なら送金できません。送金のガス代が0.0008 ETHで、1 ETH = 50万円なら、約400円分のETHを用意する必要があります。通常のイーサリアム上の送金では、USDCでガス代を払うことはできません。","mistakes":["トークンを送るのにガス代用のネイティブコインが必要なことを知らず、送金できなくなること。","同じ名前のトークンなら、どのチェーンに送っても届くと考えること。","コントラクトアドレスを確認せず、名前とシンボルだけで偽トークンを本物だと判断すること。"],"faq":[{"q":"USDTはコインですか、トークンですか？","a":"USDTは複数のブロックチェーン上で発行されるトークンです。イーサリアム版やトロン版などがあり、送金時は送り手と受け手で同じチェーンを選ぶ必要があります。"},{"q":"トークンは誰でも発行できますか？","a":"技術的には、スマートコントラクトを使えば誰でも比較的簡単に発行できます。そのため、発行者や供給量、コントラクトアドレスの確認が重要です。"}],"title":"コインとトークンの違いとは？暗号資産の基本を解説","description":"暗号資産のコインとトークンの違い、トークン送金にガス代が必要な理由、送金時にチェーンを合わせる重要性を解説します。","related":[["layer-1","レイヤー1（L1）","レイヤー1（L1）とは、ビットコイン、イーサリアム、ソラナのように、独自のネットワークで取引の検証と記録を完結させる基盤となるブロックチェーンのことです。"],["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["governance-token","ガバナンストークン","ガバナンストークンとは、DeFiやDAOなどのプロジェクトで、運営方針や仕様変更に関する投票に参加する権利を表すトークンです。"],["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。"],["altcoin","アルトコイン","アルトコインとは、ビットコイン以外の暗号資産の総称で、イーサリアムやソラナのような大型銘柄から、新しく小規模な銘柄までを含みます。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"ja","term":"ミームコイン","aka":["Memecoin","ミームトークン"],"short":"ミームコインとは、ネット上のジョークや動物、キャラクター、流行などを題材にした暗号資産で、実用性よりもコミュニティの話題性で価格が動きやすい銘柄のことです。","body":["代表例は、柴犬のミームから生まれたドージコイン（DOGE）や、その後に登場した柴犬コイン（SHIB）です。近年はソラナなどのチェーン上で誰でも簡単にミームコインを発行できるサービスが広がり、毎日大量の新しい銘柄が生まれています。",["ミームコインの価格は、SNSでの話題、著名人の発言、取引所への",["上場","token-listing"],"などで急騰と急落を繰り返します。多くは明確な収益源や用途を持たないため、関心が薄れると価格が大きく下がることがあります。"],["新しく発行された銘柄には、開発者が大量のトークンを持っていて一気に売り抜ける「",["ラグプル","rug-pull"],"」や、",["流動性","liquidity"],"が少なく売りたくても売れないケースもあります。買う前に、上位保有者の保有比率、",["流動性プール","liquidity-pool"],"がロックされているか、コントラクトに売却制限がないかを確認しましょう。"]],"example":"例えば、価格0.0001ドルのミームコインを3,000万トークン（3,000ドル分）買ったとします。価格が0.00015ドルに上がれば評価額は4,500ドルですが、0.00002ドルまで下がれば600ドルになり、2,400ドル（80%）の損失です。小型のミームコインでは、この程度の変動が短期間で起こることも珍しくありません。","mistakes":["SNSで話題になってから急いで買い、高値をつかむこと。","上位ウォレットの保有比率や流動性を確認せずに新規銘柄を買うこと。","失っても生活に困らない額を超えて資金を入れること。"],"faq":[{"q":"ミームコインとアルトコインの違いは何ですか？","a":"ミームコインはアルトコインの一種で、話題性やコミュニティを主な価値の源泉とする銘柄を指します。"},{"q":"ミームコインで詐欺を避けるにはどうすればいいですか？","a":"発行直後の銘柄では、開発者の保有比率、流動性のロック、売却制限の有無を確認します。名前が有名銘柄に似た偽物も多いため、コントラクトアドレスも必ず照合しましょう。"}],"title":"ミームコインとは？特徴と買う前の注意点","description":"ミームコインの意味と代表例、価格が急変する理由、ラグプルなど購入前に確認すべきポイントを解説します。","related":[["altcoin","アルトコイン","アルトコインとは、ビットコイン以外の暗号資産の総称で、イーサリアムやソラナのような大型銘柄から、新しく小規模な銘柄までを含みます。"],["rug-pull","ラグプル","ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"ja","term":"HODL（ガチホ）","aka":["ガチホ","ホドル"],"short":"HODL（ガチホ）とは、価格の上下に関係なく暗号資産を売らずに長期保有し続ける投資スタイルのことで、日本では「ガチホ」とも呼ばれます。","body":["語源は2013年に海外の掲示板で「HOLD」を「HODL」とタイプミスした投稿で、後から「Hold On for Dear Life（必死にしがみつけ）」の略とも言われるようになりました。日本語の「ガチホ（ガチでホールド）」もほぼ同じ意味で使われます。",["HODLの考え方は、短期の値動きを予測しようとせず、長期的な価値に期待して保有を続けることです。売買の回数が少ないため、取引手数料や",["スプレッド","bid-ask-spread"],"のコストを抑えられ、感情的な売買を避けやすいという利点があります。"],["一方で、保有中に50%以上の下落を何度も経験する可能性があり、その間も売らずにいられる資金であることが前提です。また、長期保有では保管方法が重要になります。取引所に預けたままにするか、",["ハードウェアウォレット","hardware-wallet"],"などで自己管理するかを、リスクを比べて選びましょう。"]],"example":["例えば、毎月1万円分の",["ビットコイン","bitcoin"],"を3年間（36回）買い続け、合計36万円を投じたとします。平均取得単価が800万円なら保有量は0.045 BTCです。価格が1,000万円なら評価額は45万円、600万円なら27万円になります。HODLは、この幅の上下を受け入れたうえで保有を続ける戦略だと言えます。"],"mistakes":["生活資金まで投じてしまい、下落時に売らざるを得なくなること。","保有銘柄を見直さず、開発が事実上止まったプロジェクトのトークンまで持ち続けること。","長期保有なのに、保管方法やシードフレーズのバックアップを後回しにすること。"],"faq":[{"q":"HODLとガチホは同じ意味ですか？","a":"ほぼ同じ意味で、価格が上下しても売らずに長期保有することを指します。ガチホは日本の暗号資産コミュニティでよく使われる言い方です。"},{"q":"HODLは誰にでも向いていますか？","a":"大きな下落が続いても売らずにいられる資金と心構えが必要です。近いうちに使う予定のお金には向きません。"}],"title":"HODL（ガチホ）とは？意味と長期保有の注意点","description":"HODL（ガチホ）の意味と語源、長期保有のメリットとリスク、保管方法で気をつけるべき点を具体例で解説します。","related":[["dollar-cost-averaging","ドルコスト平均法（DCA）","ドルコスト平均法（DCA）とは、価格に関係なく一定の金額を定期的に買い続けることで、購入タイミングを分散させる投資手法です。"],["cold-wallet","コールドウォレット（コールドストレージ）","コールドウォレットとは、秘密鍵をインターネットから切り離した環境で保管する暗号資産の保管方法で、遠隔からのハッキングを受けにくいのが特徴です。"],["bear-market","弱気相場（ベアマーケット）","弱気相場（ベアマーケット）とは、価格が長期間にわたって下落傾向を続け、悲観的な見方が市場に広がっている相場のことです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"ja","term":"流動性プール（リクイディティプール）","aka":["リクイディティプール","LP","liquidity pool","プール"],"short":"流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。","body":[[["流動性","liquidity"],"を提供する人を流動性提供者（LP）と呼びます。たとえばETHとUSDCのプールなら、同じ価値分のETHとUSDCを預け、プール内の持ち分を表すLPトークンを受け取るのが一般的な仕組みです。"],["トレーダーがプールで交換するたびに手数料が発生し、持ち分に応じてLPに分配されます。取引が多いプールほど手数料収入は増えますが、同時にトークン価格の変動による",["インパーマネントロス","impermanent-loss"],"も負います。"],["プールにはリスクもあります。",["スマートコントラクト","smart-contract"],"のバグ、詐欺トークンのペア、開発者による流動性の引き揚げ（",["ラグプル","rug-pull"],"）などです。提供前にプールの規模、",["取引量","trading-volume"],"、ペアのトークンの信頼性を確認しましょう。"]],"example":"総額100万ドルのETH/USDCプールに、あなたが1万ドル分（ETHとUSDCを5,000ドルずつ）を預けたとします。持ち分は1%です。このプールで1日に500万ドルの取引があり、手数料率が0.3%なら、1日の手数料は15,000ドルで、あなたの取り分は150ドルです。ただし取引量は日々変わり、同じ期間にETH価格が大きく動けば、手数料を上回るインパーマネントロスが出ることもあります。","mistakes":["表示されている年利だけを見て、取引量が続く前提で収益を計算すること。","LPトークンを紛失したり誤って売ったりして、預けた資産を引き出せなくなること。","無名のトークンとのペアに流動性を提供し、ラグプルに巻き込まれること。"],"faq":[{"q":"流動性プールに預けた資産はいつでも引き出せますか？","a":"多くのDEXではLPトークンを返せばいつでも引き出せます。ただし引き出すときのトークンの比率は預けたときと変わっている場合があり、ガス代もかかります。"},{"q":"ステーブルコイン同士のプールなら安全ですか？","a":"価格差が小さいため、インパーマネントロスは小さくなりやすいです。ただし片方がペッグを失う（デペッグ）と大きな損失が出ることがあり、コントラクトのリスクも残ります。"}],"title":"流動性プールとは？仕組みと手数料収入・リスク","description":"DEXの流動性プール（リクイディティプール）の意味、LPトークンと手数料収入の仕組み、インパーマネントロスなどのリスクを解説します。","related":[["amm","AMM（自動マーケットメーカー）","AMM（自動マーケットメーカー）とは、板で売り手と買い手を突き合わせる代わりに、流動性プールと数式で自動的に価格を決めて取引を成立させる仕組みです。"],["impermanent-loss","インパーマネントロス（変動損失）","インパーマネントロスとは、AMMの流動性プールに資産を預けている間にトークンの価格比が変わることで、単に保有していた場合より資産価値が少なくなる損失のことです。"],["yield-farming","イールドファーミング","イールドファーミングとは、DeFiのプロトコルに暗号資産を預けたり流動性を提供したりして、手数料や報酬トークンなどの利回りを得る運用方法です。"],["rug-pull","ラグプル","ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"ja","term":"パーペチュアルDEX（オンチェーン無期限先物）","aka":["Perp DEX","パープDEX","分散型無期限先物取引所","オンチェーンパーペチュアル"],"short":"パーペチュアルDEXとは、無期限先物（パーペチュアル）を、自分のウォレットから証拠金を入れてブロックチェーン上で取引できる分散型取引所です。","body":[["Hyperliquid、dYdX、GMXなどが代表例です。",["中央集権型取引所","centralized-exchange"],"と同じように、",["ロング","long-and-short"],"やショート、",["レバレッジ","leverage"],"、",["資金調達率（ファンディングレート）","funding-rate"],"、",["強制ロスカット（清算）","liquidation"],"の仕組みがあります。違いは、資産を取引所に預けずに",["ウォレット","crypto-wallet"],"とスマートコントラクトで管理する点です。"],"仕組みはプロトコルによって大きく異なります。独自のブロックチェーン上でオンチェーンの板を運用するもの、流動性プールが取引相手になるもの、オラクル価格で約定するものなどがあります。資金調達率の精算間隔や清算のルールも、それぞれの仕様を確認する必要があります。","リスクは、レバレッジ取引そのもののリスクに加えて、スマートコントラクトやブリッジの脆弱性、オラクルの異常、流動性の薄さなどです。日本の国内業者で認められているレバレッジ上限（個人は2倍）とは異なる高倍率が提供されていることもあり、清算の仕組みを理解してから使いましょう。"],"example":"あなたが1,000 USDCを証拠金に、5倍のレバレッジでBTCの無期限先物を5,000 USDC分ロングしたとします。BTCが10%上がれば利益は500 USDCで、証拠金に対して50%です。逆に約18%下がると、損失が約900 USDCになり、維持証拠金を下回って清算される可能性があります。正確な清算価格は、取引所ごとの維持証拠金率や手数料で変わります。","mistakes":["分散型だから清算されないと誤解し、高いレバレッジをかけること。","資金調達率の精算間隔を確認せず、長期保有でコストが積み上がること。","ブリッジで資金を入金する際、偽サイトや誤ったネットワークを使うこと。"],"faq":[{"q":"パーペチュアルDEXと中央集権型取引所の先物の違いは何ですか？","a":"主な違いは資産の管理方法です。DEXでは証拠金を自分のウォレットとスマートコントラクトで管理し、取引記録もオンチェーンで確認できます。一方で、サポート体制や流動性はCEXの方が厚いことが多いです。"},{"q":"パーペチュアルDEXに本人確認は必要ですか？","a":"多くのパーペチュアルDEXはウォレット接続だけで利用できますが、地域によって利用を制限しているものもあります。居住国のルールや利用規約を確認してください。"}],"title":"パーペチュアルDEXとは？オンチェーン無期限先物の仕組み","description":"パーペチュアルDEX（オンチェーン無期限先物）の意味、HyperliquidやdYdXなどの仕組み、CEXとの違いと清算・コントラクトのリスクを解説します。","related":[["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。"]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"ja","term":"コピートレード","aka":["コピートレーディング","copy trading","ミラートレード"],"short":"コピートレードとは、取引所上で選んだ他のトレーダーの売買を、自分の口座で自動的に同じように再現する仕組みのことです。","body":["コピーしたいトレーダー（リードトレーダー）を選び、投入する金額や1回あたりの上限を設定すると、そのトレーダーが注文するたびに、自分の口座でも比率に応じた注文が自動で出されます。OKX、Bybit、Bitgetなどの取引所がコピートレードの機能を提供しています。",["多くの場合、利益が出たときにその一部（利益配分）をリードトレーダーに支払う仕組みです。対象は現物と先物の両方があり、先物のコピーでは",["レバレッジ","leverage"],"もコピーされるため、損失が大きくなることがあります。"],"表示される過去の成績は、あくまで過去のものです。短期間に高いレバレッジで大きなリターンを出したトレーダーは、同じ方法で大きな損失を出すこともあります。勝率だけでなく、最大ドローダウン（資産のピークからの最大下落率）や運用期間、運用資産の規模を確認しましょう。"],"example":["あなたが1,000 USDTで、あるリードトレーダーをコピーしたとします。リードトレーダーが自分の資金10,000 USDTのうち20%を使い、10倍のレバレッジでBTCの",["ロング","long-and-short"],"を開いた場合、あなたの口座でも資金の20%である200 USDTが証拠金になり、2,000 USDT分のロングが開かれます。BTCが5%上がると利益は100 USDTで、利益配分が10%なら10 USDTを支払い、手元には90 USDTが残ります。逆にBTCが5%下がれば100 USDTの損失で、利益配分は発生しません。"],"mistakes":["短期間の収益率ランキングだけを見て、リスクの大きいトレーダーを選んでしまう。","1回あたりの上限や損切りの設定をせず、資金のすべてをコピーに回す。","先物のコピーではレバレッジもそのまま反映され、清算されることがある点を見落とす。"],"faq":[{"q":"コピートレードで損をすることはありますか？","a":"はい、リードトレーダーが損失を出せば、あなたの口座でも同じ比率で損失が出ます。先物の場合は清算されて証拠金を失うこともあります。"},{"q":"コピートレードの手数料はいくらですか？","a":"通常の取引手数料に加えて、利益の一部をリードトレーダーに支払う仕組みが一般的です。配分の比率は取引所やトレーダーごとに違うので、コピー前に確認してください。"}],"title":"コピートレードとは？仕組みと選び方の注意点","description":"コピートレードの意味と仕組み、利益配分とレバレッジの扱い、リードトレーダーを選ぶときに見るべき指標と注意点を解説します。","related":[["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["risk-reward-ratio","リスクリワードレシオ（損益比率）","リスクリワードレシオとは、1回の取引で想定する損失額（リスク）と利益額（リワード）の比率のことで、例えば損失100に対して利益200なら1対2と表します。"],["grid-trading-bot","グリッドトレードボット","グリッドトレードボットとは、設定した価格帯をいくつかの網目（グリッド）に分け、価格が下がれば買い、上がれば売る指値注文を自動で繰り返す取引ツールのことです。"]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
